          dietOrders.push(C.diet(dietName, from, w[0], 'High protein (1.5-2 g/kg/day) and 30-35 kcal/kg/day for wound healing; oral nutrition supplement three times daily; small frequent meals. Glucose check before meals.'));
          dietOrders.push(C.diet('NPO', w[0], w[1], 'NPO after midnight for operating room debridement/grafting; sips of water with essential medications allowed until 2 hours before. Glucose every 6 hours.'));
