        isolation: 'None', fluidSensitive: false, famHxExtra: 'No known family history of immune deficiency or bleeding disorders.',
        flags: { npo: npoW, hypotension: [[0, pressOff + 6]], preop: [[0, orH1]], surgeryWindow: [[0, orEnd4 + 24]], postop: [[orEnd1, 9999]] },
